// PlugAI project — ESP32-C3-DevKitM-1 (ESP-IDF v5.5).
// Traffic light with pedestrian push button:
//   RED 5 s -> GREEN 4 s -> YELLOW 2 s, repeating.
//   Pressing the pedestrian button during GREEN (sampled every 10 ms, first
//   press per green phase only) ends GREEN 1 s after the press, then the
//   normal YELLOW phase runs. Presses during RED/YELLOW are ignored.
// Wiring: GPIO4 -> tl1.R, GPIO5 -> tl1.Y, GPIO6 -> tl1.G, tl1.GND -> board GND,
//         GPIO7 -> btn1.1, btn1.2 -> board GND (internal pull-up, pressed = LOW).
// The traffic-light module is common cathode with on-board 220 ohm resistors,
// so driving a GPIO high turns that lamp on and low turns it off.

#include <stdio.h>
#include <stdbool.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "driver/gpio.h"

#define PIN_RED    GPIO_NUM_4
#define PIN_YELLOW GPIO_NUM_5
#define PIN_GREEN  GPIO_NUM_6
#define PIN_BTN    GPIO_NUM_7

#define T_RED_MS    5000
#define T_GREEN_MS  4000
#define T_YELLOW_MS 2000
#define T_PED_MS    1000
#define POLL_MS     10

static void all_off(void)
{
    gpio_set_level(PIN_RED, 0);
    gpio_set_level(PIN_YELLOW, 0);
    gpio_set_level(PIN_GREEN, 0);
}

/* GREEN phase: normal length T_GREEN_MS, shortened to "press + 1 s" when the
 * pedestrian button is pressed while green is on (first press only). */
static void phase_green(void)
{
    gpio_set_level(PIN_RED, 0);
    gpio_set_level(PIN_YELLOW, 0);
    gpio_set_level(PIN_GREEN, 1);
    printf("GREEN\n");

    uint32_t elapsed = 0;
    uint32_t limit = T_GREEN_MS;
    bool ped_seen = false;

    while (elapsed < limit) {
        vTaskDelay(pdMS_TO_TICKS(POLL_MS));
        elapsed += POLL_MS;

        if (!ped_seen && gpio_get_level(PIN_BTN) == 0) { /* pressed = LOW */
            ped_seen = true;
            uint32_t target = elapsed + T_PED_MS;        /* 1 s after the press */
            if (target < limit) {
                limit = target;                          /* shorten, never extend */
            }
            printf("PEDESTRIAN\n");
        }
    }

    gpio_set_level(PIN_GREEN, 0);
}

void app_main(void)
{
    gpio_config_t out_cfg = {
        .pin_bit_mask = (1ULL << PIN_RED) | (1ULL << PIN_YELLOW) | (1ULL << PIN_GREEN),
        .mode = GPIO_MODE_OUTPUT,
        .pull_up_en = GPIO_PULLUP_DISABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type = GPIO_INTR_DISABLE,
    };
    ESP_ERROR_CHECK(gpio_config(&out_cfg));

    gpio_config_t in_cfg = {
        .pin_bit_mask = (1ULL << PIN_BTN),
        .mode = GPIO_MODE_INPUT,
        .pull_up_en = GPIO_PULLUP_ENABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type = GPIO_INTR_DISABLE,
    };
    ESP_ERROR_CHECK(gpio_config(&in_cfg));

    /* Start with every lamp off to avoid a spurious flash at power-up. */
    all_off();

    printf("PlugAI traffic light + pedestrian button: RED 5s -> GREEN 4s -> YELLOW 2s;"
           " button during GREEN ends green 1s after press\n");

    while (1) {
        /* Phase RED (pedestrian button ignored) */
        gpio_set_level(PIN_RED, 1);
        gpio_set_level(PIN_YELLOW, 0);
        gpio_set_level(PIN_GREEN, 0);
        printf("RED\n");
        vTaskDelay(pdMS_TO_TICKS(T_RED_MS));

        /* Phase GREEN (pedestrian button can shorten it) */
        phase_green();

        /* Phase YELLOW (pedestrian button ignored) */
        gpio_set_level(PIN_RED, 0);
        gpio_set_level(PIN_YELLOW, 1);
        gpio_set_level(PIN_GREEN, 0);
        printf("YELLOW\n");
        vTaskDelay(pdMS_TO_TICKS(T_YELLOW_MS));
    }
}
